deep_text(o,"천붕","본가의 장로 하나가 맹의 회합에서 돌아온 뒤로 웃음이 늘었다고 한다. 가주가 그 장로를 사당에 들이지 않는다.",
 "맹의 진중에서 모용의 창이 모용의 장로를 겨누었다는 소문이 돈다. 불을 품은 자가 누구였는지 세가는 말하지 않는다.")
deeper("외전모용_3","나루 건너편에 잿빛 가사의 승려도 서 있다. 사공이 말한다. \"혈교도 그 창을 찾소. 백 년 전 천마와 맞선 창이면 피를 많이 마셨을 거라나.\"",
 "나루의 붉은 소매들 가운데 정수리가 그을린 자가 있다. 사공이 말한다. \"장백의 흰 범을 잡으러 가는 길이라오. 창도 찾고 범도 잡고.\"",
 "사공이 내 단전 쪽을 본다. \"요즘 강을 건너는 무인은 단전부터 짚게 하오. 중원의 어른들이 불을 품었다더군.\"")
deeper("외전모용_끝","오두막 밖에 잿빛 가사 한 벌이 눈에 묻혀 있다. 나곤이 말한다. \"창을 사겠다고 왔다가 돌아가지 못했다.\"",
 "오두막 벽에 흰 범의 가죽이 걸려 있다. 나곤이 말한다. \"붉은 소매가 내단을 뽑고 버린 것을 거두었다.\"",
 "나곤이 내 단전에 손바닥을 댄다. \"차구나. 중원에서 온 놈들은 다 뜨겁더니.\"")
deep_choice("외전모용_2","혈풍",C("삼꾼들에게 혈계 대신 관의 표를 사 준다",O("삼꾼들이 붉은 손바닥을 내려다보다 표를 받았다. 잿빛 가사의 승려가 혀를 찼다. 은자가 많이 들었다.",alignment=AL(j=40),silver=-40,stats={"mind":5},flags=["모용_무덤","모용_혈풍"])))
deep_choice("외전모용_4","겁화",C("산해관 성벽의 겁화대 무사를 창으로 꿰뚫는다",O("검은 강기가 창끝에 부딪쳐 불꽃을 튀겼다. 세 번째에 꿰뚫었다. 직계의 젊은이들이 성벽 위에서 그것을 보았다.",battle="겁화대마졸",foe="산해관을 허무는 겁화대 무사",foe_line="\"관정을 받은 몸이다. 창 따위.\"",lose_flags=["모용_산해관"],alignment=AL(j=40),stats={"external":6,"martial":4},fame=25,flags=["모용_산해관","모용_귀가","모용_겁화"])))
deep_choice("외전모용_5","천붕",C("모용백의 단전을 먼저 짚게 해 달라고 청한다",O("모용백이 웃으며 배를 내밀었다. 차가웠다. \"본가에도 짚을 사람이 하나 있지. 가주께서 사당에 들이지 않는 그 장로 말이다. 네가 돌아오면 짚어 다오.\" 겨룸은 그 뒤에 했다.",battle="외전_모용백",spar=True,lose_next="물러남",alignment=AL(j=30),stats={"martial":7,"mind":4},mastery=18,full_growth=True,flags=["모용_종손","모용_천붕"])))
deep_event("모용_혈풍삼꾼",o,"혈풍",[2,3],"붉은 손바닥의 삼꾼",
 "삼밭에서 삼꾼 하나가 미친 듯이 땅을 판다. 손바닥에 붉은 인이 박혔다. 혈계를 맺은 지 나흘째라 한다. 힘이 빠지자 삼을 다 캐야 계값을 치를 수 있다고 운다.",
 [C("계값을 대신 치르고 삼꾼을 쉬게 한다",O("잿빛 가사의 승려가 은자를 받고 인을 풀어 주었다. 삼꾼은 사흘을 앓았다.",alignment=AL(j=40),silver=-30,stats={"mind":4},flags=["모용_혈풍"])),
  C("계를 맺어 준 승려를 찾아가 꺾는다",O("승려가 쓰러지자 삼꾼들의 손바닥이 식었다. 삼밭에 다시 잿빛 가사가 오지 않았다.",battle="혈교수련자",foe="삼밭의 혈계승 원각",foe_line="\"삼꾼의 피는 삼처럼 쓰다.\"",alignment=AL(j=30),stats={"martial":4},flags=["모용_혈풍"])),
  C("삼꾼이 캔 삼을 헐값에 사 준다",O("삼꾼은 고마워했다. 장터에서 그 삼을 다섯 배에 팔았다.",alignment=AL(s=40),silver=60))])
deep_event("모용_겁화흰범",o,"겁화",[3,4],"흰 범의 발자국",
 "눈 위에 큰 발자국이 이어진다. 흰 범의 것이다. 그 뒤를 붉은 소매의 사냥꾼 셋이 쫓는다. 발자국에 핏방울이 섞였다.",
 [C("사냥꾼들을 막는다",O("사냥꾼들이 눈 속에 쓰러졌다. 흰 범은 산 위에서 한 번 돌아보고 사라졌다.",battle="마교척살조",foe="장백을 넘어온 내단 사냥꾼",foe_line="\"범 한 마리에 겁화대 하나다.\"",alignment=AL(j=40),stats={"external":4,"martial":3},flags=["모용_흰범"])),
  C("범보다 먼저 가서 범을 숨긴다",O("범의 발자국 위로 내 발자국을 덮었다. 사냥꾼들은 길을 잃고 내려갔다.",alignment=AL(j=30),stats={"mind":4,"martial":2},flags=["모용_흰범"])),
  C("사냥꾼들에게서 화로로 가는 길을 캐낸다",O("그들은 국경의 나루에서 배를 탄다고 했다. 그 나루가 내가 건넌 나루였다.",alignment=AL(s=20),stats={"mind":4}))])
deep_event("모용_천붕장로",o,"천붕",[3,4],"웃는 장로",
 "본가의 장로 하나가 요동까지 나를 찾아왔다. 가주가 사당에 들이지 않는 그 장로다. \"방계가 창을 찾는다니 내가 도와주마. 그 창은 세가를 위해 쓰여야 한다. 맹을 위해서가 아니라.\" 장로의 웃음이 길다.",
 [C("장로의 단전을 짚는다",O("뜨거웠다. 장로가 웃음을 멈추지 못했다. 창으로 불을 눌렀다. 깨어난 장로는 맹의 회합에서 돌아온 뒤의 일을 기억하지 못했다.",battle="잠화무인",foe="불을 품은 모용의 장로 모용승",foe_line="\"세가를 위해서다. 다 세가를 위해서야.\"",alignment=AL(j=30),stats={"martial":4,"mind":3},flags=["모용_천붕"])),
  C("도움을 정중히 사양하고 길을 떠난다",O("장로는 웃으며 돌아갔다. 가주에게 그 일을 편지로 적어 보냈다.",stats={"mind":4},flags=["모용_천붕"])),
  C("장로의 도움을 받고 창의 행방을 나눈다",O("장로는 사람을 보내 길을 열어 주었다. 장백까지의 길이 빨라졌다. 그 사람들도 이따금 웃었다.",alignment=AL(s=20,m=20),stats={"martial":3}))])
depth_lines("외전모용_족보","족보에 이름이 오른 날 요동의 삼꾼들이 삼 한 뿌리를 보냈다. 붉은 손바닥이 다 식은 손으로 캔 삼이었다.",
 "족보에 이름이 오른 해 산해관의 성벽에 연운창 자국이 하나 남았다. 겁화대의 강기를 뚫은 자국이다.",
 "족보에 이름이 오른 날 가주는 사당에 들이지 않던 장로의 일을 〈그〉에게 맡겼다. 〈그〉는 먼저 단전을 짚었다.")
depth_lines("외전모용_창주인","북방의 창객은 혈교의 승려가 삼밭에 오지 못하게 했다.",
 "북방의 창객은 장백의 흰 범을 지켰다. 사냥꾼들은 그 창을 피해 다른 산으로 갔다.",
 "북방의 창객에게는 단전을 짚는 손이 오지 않았다. 눈 속까지 의심을 들고 오는 사람은 없었다.")
depth_lines("외전모용_방계","담 밖의 방계는 북방에서 들려오는 혈교 소식을 연무장에서 들었다.",
 "담 밖의 방계는 산해관의 겁화대 이야기를 아이들에게 해 주었다. 창을 더 오래 잡으라고.",
 "담 밖의 방계에게는 본가의 의심이 닿지 않았다. 족보에 없는 이름은 짚을 까닭도 없었다.")
